def max_cookies(n, k, a, b):
    def cookies_with_powder(x):
        # Calculate cookies that can be made with x cookies and magic powder
        cookies = 0
        for i in range(n):
            if b[i] >= a[i] * x:
                cookies += x
            else:
                cookies += b[i] // a[i]
        return cookies

    low, high = 0, k
    while low < high:
        mid = (low + high + 1) // 2
        if cookies_with_powder(mid) <= k:
            low = mid
        else:
            high = mid - 1

    # Calculate the remaining magic powder after using it optimally
    cookies = cookies_with_powder(low)
    remaining_powder = k - cookies

    # Use the remaining magic powder on the least efficient ingredient
    max_cookies = low
    for i in range(n):
        if b[i] < a[i] * low:
            magic_needed = a[i] * low - b[i]
            if magic_needed <= remaining_powder:
                max_cookies += magic_needed // a[i]
                remaining_powder -= magic_needed
            else:
                max_cookies += remaining_powder // a[i]
                break

    return max_cookies

